        ((J2DPicture*)mCkPanes[mCkBufIdx][16].pane)->setBlackWhite(JUtility::TColor(0, 0, 0, 0), JUtility::TColor(0, 0, 0, 255));
        mCkPanes[mCkBufIdx][16].pane->setAlpha(64);
