int dMenu_Fmap2_c::getButtonIconMode() {
    int ret;
    switch (getCtActive()) {
    case 0:
        ret = FMAP2_BTN_ICON_FMAP;
        break;
    case 1:
        if (mCollectMapNum == 0) {
            ret = FMAP2_BTN_ICON_NO_MAP;
        } else {
            ret = mButtonIconMode;
        }
        break;
    }
    return ret;
}

